package com.zhineng.platform.evaluation.publicservice.repository;
import java.sql.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.support.*;import org.springframework.stereotype.Repository;
@Repository public class PublicEvaluationRepository {
 private final JdbcTemplate jdbc; public PublicEvaluationRepository(JdbcTemplate jdbc){this.jdbc=jdbc;}
 public List<Map<String,Object>> orgs(){return jdbc.queryForList("SELECT id,unit_code,unit_name FROM org_units WHERE status='ACTIVE' AND unit_type NOT IN('ROOT','GROUP') ORDER BY sort_order,id");}
 public List<Map<String,Object>> items(){return jdbc.queryForList("SELECT i.*,o.unit_name,o.unit_code FROM public_service_items i JOIN org_units o ON o.id=i.org_unit_id ORDER BY i.status,i.item_code");}
 public Map<String,Object> item(long id){return one("SELECT i.*,o.unit_name FROM public_service_items i JOIN org_units o ON o.id=i.org_unit_id WHERE i.id=?",id);}
 public long addItem(String code,String name,long org,String desc,String status,long uid){return insert("INSERT INTO public_service_items(item_code,item_name,org_unit_id,description,status,created_by,updated_by)VALUES(?,?,?,?,?,?,?)",code,name,org,desc,status,uid,uid);}
 public int updateItem(long id,String code,String name,long org,String desc,String status,long uid){return jdbc.update("UPDATE public_service_items SET item_code=?,item_name=?,org_unit_id=?,description=?,status=?,updated_by=?,updated_at=strftime('%Y-%m-%dT%H:%M:%SZ','now') WHERE id=?",code,name,org,desc,status,uid,id);}
 public Map<String,Object> org(long id){return one("SELECT * FROM org_units WHERE id=? AND status='ACTIVE' AND unit_type NOT IN('ROOT','GROUP')",id);}
 public Map<String,Object> orgByCode(String code){return one("SELECT * FROM org_units WHERE unit_code=? COLLATE NOCASE AND status='ACTIVE' AND unit_type NOT IN('ROOT','GROUP')",code);}
 public long addEvaluation(String no,String source,String sourceId,Long batch,long org,Long item,String sourceItem,Integer c,Integer a,Integer t,Integer l,double overall,String comment,String sentiment,boolean anonymous,String name,String phone,String idNo,String at,String raw,long uid){
  return insert("INSERT INTO public_evaluations(evaluation_no,source,source_record_id,import_batch_id,org_unit_id,service_item_id,source_service_item,convenience_score,attitude_score,timeliness_score,clarity_score,overall_score,comment_text,sentiment,is_anonymous,evaluator_name,evaluator_phone,evaluator_id_no,evaluated_at,raw_json,created_by)VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",no,source,sourceId,batch,org,item,sourceItem,c,a,t,l,overall,comment,sentiment,anonymous?1:0,name,phone,idNo,at,raw,uid);
 }
 public List<Map<String,Object>> evaluations(Long org,String source,String status,Integer minScore,Boolean anonymous){return evaluations(org,source,status,minScore,null,anonymous,null,null,1,10000);}
 public List<Map<String,Object>> evaluations(Long org,String source,String status,Integer minScore,Integer maxScore,Boolean anonymous,String fromDate,String toDate,int page,int size){
  StringBuilder sql=new StringBuilder("SELECT e.id,e.evaluation_no,e.source,e.org_unit_id,o.unit_name,e.service_item_id,COALESCE(i.item_name,e.source_service_item) service_item_name,e.overall_score,e.comment_text,e.sentiment,e.sentiment_source,e.is_anonymous,e.process_status,e.process_opinion,e.evaluated_at,e.created_at,CASE WHEN e.is_anonymous=1 THEN '匿名用户' WHEN e.evaluator_name IS NULL THEN '-' ELSE substr(e.evaluator_name,1,1)||'**' END masked_name,CASE WHEN e.evaluator_phone IS NULL THEN '-' WHEN length(e.evaluator_phone)>=7 THEN substr(e.evaluator_phone,1,3)||'****'||substr(e.evaluator_phone,-4) ELSE '****' END masked_phone FROM public_evaluations e JOIN org_units o ON o.id=e.org_unit_id LEFT JOIN public_service_items i ON i.id=e.service_item_id WHERE 1=1");
  List<Object> p=new ArrayList<>();appendEvaluationFilters(sql,p,org,source,status,minScore,maxScore,anonymous,fromDate,toDate);sql.append(" ORDER BY e.evaluated_at DESC,e.id DESC LIMIT ? OFFSET ?");p.add(size);p.add((page-1)*size);return jdbc.queryForList(sql.toString(),p.toArray());
 }
 public long countEvaluations(Long org,String source,String status,Integer minScore,Integer maxScore,Boolean anonymous,String fromDate,String toDate){StringBuilder sql=new StringBuilder("SELECT count(*) FROM public_evaluations e WHERE 1=1");List<Object>p=new ArrayList<>();appendEvaluationFilters(sql,p,org,source,status,minScore,maxScore,anonymous,fromDate,toDate);return jdbc.queryForObject(sql.toString(),Long.class,p.toArray());}
 private void appendEvaluationFilters(StringBuilder sql,List<Object>p,Long org,String source,String status,Integer minScore,Integer maxScore,Boolean anonymous,String fromDate,String toDate){if(org!=null){sql.append(" AND e.org_unit_id=?");p.add(org);}if(source!=null&&!source.isBlank()){sql.append(" AND e.source=?");p.add(source);}if(status!=null&&!status.isBlank()){sql.append(" AND e.process_status=?");p.add(status);}if(minScore!=null){sql.append(" AND e.overall_score>=?");p.add(minScore);}if(maxScore!=null){sql.append(" AND e.overall_score<=?");p.add(maxScore);}if(anonymous!=null){sql.append(" AND e.is_anonymous=?");p.add(anonymous?1:0);}if(fromDate!=null&&!fromDate.isBlank()){sql.append(" AND date(e.evaluated_at)>=date(?)");p.add(fromDate);}if(toDate!=null&&!toDate.isBlank()){sql.append(" AND date(e.evaluated_at)<=date(?)");p.add(toDate);}}
 public Map<String,Object> evaluation(long id,boolean sensitive){String fields=sensitive?",e.evaluator_name,e.evaluator_phone,e.evaluator_id_no":"";return one("SELECT e.id,e.evaluation_no,e.source,e.source_record_id,e.import_batch_id,e.org_unit_id,e.service_item_id,e.source_service_item,e.convenience_score,e.attitude_score,e.timeliness_score,e.clarity_score,e.overall_score,e.comment_text,e.sentiment,e.sentiment_source,e.is_anonymous,e.evaluated_at,e.process_status,e.process_opinion,e.processed_by,e.processed_at,e.created_at,o.unit_name,i.item_name"+fields+" FROM public_evaluations e JOIN org_units o ON o.id=e.org_unit_id LEFT JOIN public_service_items i ON i.id=e.service_item_id WHERE e.id=?",id);}
 public int process(long id,String status,String opinion,long uid){return jdbc.update("UPDATE public_evaluations SET process_status=?,process_opinion=?,processed_by=?,processed_at=strftime('%Y-%m-%dT%H:%M:%SZ','now') WHERE id=?",status,opinion,uid,id);}
 public int sentiment(long id,String sentiment,long uid){return jdbc.update("UPDATE public_evaluations SET sentiment=?,sentiment_source='MANUAL',processed_by=? WHERE id=?",sentiment,uid,id);}
 public long requestAccess(long eid,String reason,String fields,long uid){return insert("INSERT INTO public_privacy_access_requests(evaluation_id,reason,requested_fields,requested_by)VALUES(?,?,?,?)",eid,reason,fields,uid);}
 public List<Map<String,Object>> requests(){return jdbc.queryForList("SELECT r.*,e.evaluation_no,u.display_name requester_name FROM public_privacy_access_requests r JOIN public_evaluations e ON e.id=r.evaluation_id LEFT JOIN sys_users u ON u.id=r.requested_by ORDER BY r.id DESC");}
 public Map<String,Object> request(long id){return one("SELECT * FROM public_privacy_access_requests WHERE id=?",id);}
 public int reviewRequest(long id,String status,String opinion,long uid){return jdbc.update("UPDATE public_privacy_access_requests SET status=?,review_opinion=?,reviewed_by=?,reviewed_at=strftime('%Y-%m-%dT%H:%M:%SZ','now') WHERE id=? AND status='PENDING'",status,opinion,uid,id);}
 public void audit(long request,long eval,String fields,long uid){jdbc.update("INSERT INTO public_privacy_access_audits(request_id,evaluation_id,accessed_by,accessed_fields)VALUES(?,?,?,?)",request,eval,uid,fields);}
 public List<Map<String,Object>> audits(){return jdbc.queryForList("SELECT a.*,e.evaluation_no,u.display_name accessed_by_name FROM public_privacy_access_audits a JOIN public_evaluations e ON e.id=a.evaluation_id LEFT JOIN sys_users u ON u.id=a.accessed_by ORDER BY a.id DESC");}
 public long addAttachment(long eval,String original,String stored,String path,String type,String ext,long size,long uid){long aid=insert("INSERT INTO sys_attachments(business_type,business_id,original_name,stored_name,storage_path,content_type,extension,file_size,uploaded_by)VALUES('PUBLIC_EVALUATION',?,?,?,?,?,?,?,?)",eval,original,stored,path,type,ext,size,uid);insert("INSERT INTO public_evaluation_attachments(evaluation_id,attachment_id)VALUES(?,?)",eval,aid);return aid;}
 public Map<String,Object> attachment(long id){return one("SELECT a.* FROM sys_attachments a JOIN public_evaluation_attachments x ON x.attachment_id=a.id WHERE a.id=? AND a.status='ACTIVE'",id);}
 public List<Map<String,Object>> attachments(long eval){return jdbc.queryForList("SELECT a.id,a.original_name,a.content_type,a.extension,a.file_size FROM sys_attachments a JOIN public_evaluation_attachments x ON x.attachment_id=a.id WHERE x.evaluation_id=? AND a.status='ACTIVE' ORDER BY a.id",eval);}
 public long addBatch(String code,String source,String name,String type,long size,long uid){return insert("INSERT INTO public_evaluation_import_batches(batch_code,source,original_file_name,file_type,file_size,imported_by)VALUES(?,?,?,?,?,?)",code,source,name,type,size,uid);}
 public void finishBatch(long id,int total,int ok,int fail,int warn){String s=fail==0?"COMPLETED":ok==0?"FAILED":"PARTIAL_FAILED";jdbc.update("UPDATE public_evaluation_import_batches SET total_rows=?,success_rows=?,failed_rows=?,warning_rows=?,status=? WHERE id=?",total,ok,fail,warn,s,id);}
 public void addError(long batch,int row,String code,String raw,String error){jdbc.update("INSERT INTO public_evaluation_import_errors(batch_id,source_row_number,org_code,raw_json,error_message)VALUES(?,?,?,?,?)",batch,row,code,raw,error);}
 public List<Map<String,Object>> batches(){return jdbc.queryForList("SELECT * FROM public_evaluation_import_batches ORDER BY id DESC");}
 public Map<String,Object> batch(long id){return one("SELECT * FROM public_evaluation_import_batches WHERE id=?",id);}
 public List<Map<String,Object>> errors(long id){return jdbc.queryForList("SELECT * FROM public_evaluation_import_errors WHERE batch_id=? ORDER BY source_row_number",id);}
 public List<Map<String,Object>> batchRecords(long id){return jdbc.queryForList("SELECT e.id,e.evaluation_no,e.source_record_id,e.source_service_item,e.overall_score,e.sentiment,e.evaluated_at,o.unit_name FROM public_evaluations e JOIN org_units o ON o.id=e.org_unit_id WHERE e.import_batch_id=? ORDER BY e.id",id);}
 public Map<String,Object> stats(){return one("SELECT count(*) total,count(DISTINCT org_unit_id) org_count,round(avg(overall_score),2) avg_score,sum(CASE WHEN sentiment='NEGATIVE' THEN 1 ELSE 0 END) negative_count,round(100.0*sum(CASE WHEN sentiment='NEGATIVE' THEN 1 ELSE 0 END)/max(count(*),1),2) negative_rate FROM public_evaluations");}
 public List<Map<String,Object>> sourceStats(){return jdbc.queryForList("SELECT source,count(*) count,round(avg(overall_score),2) avg_score FROM public_evaluations GROUP BY source ORDER BY count DESC");}
 public Map<String,Object> one(String sql,Object...args){List<Map<String,Object>> rows=jdbc.queryForList(sql,args);return rows.isEmpty()?null:rows.get(0);}
 private long insert(String sql,Object...args){KeyHolder k=new GeneratedKeyHolder();jdbc.update(c->{PreparedStatement s=c.prepareStatement(sql,Statement.RETURN_GENERATED_KEYS);for(int i=0;i<args.length;i++)s.setObject(i+1,args[i]);return s;},k);return k.getKey().longValue();}
}
